#!/usr/bin/env node
/**
 * Converts the official WHO Child Growth Standards LMS tables (from the WHO `anthro` R package,
 * `data/who/*.txt`, tab-separated: sex(1=male,2=female), age(days), l, m, s[, loh])
 * into compact, lazily-importable TypeScript modules under `src/domain/growth/data/`.
 *
 * Output shape per module (see `src/domain/growth/lms.ts` → `LmsTable`):
 *   { male: [l, m, s][], female: [l, m, s][] }   // index === age in days, contiguous from 0
 *
 * Usage: `npm run who-data`. The generated files are committed so the build never depends on it.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC_DIR = join(ROOT, 'data', 'who');
const OUT_DIR = join(ROOT, 'src', 'domain', 'growth', 'data');
const MAX_AGE_DAYS = 1856;
const ROWS_PER_LINE = 6;

/** @type {{ input: string; output: string; indicator: string; unit: string }[]} */
const TABLES = [
  { input: 'weianthro.txt', output: 'weightForAge.ts', indicator: 'weight-for-age', unit: 'kg' },
  {
    input: 'lenanthro.txt',
    output: 'lengthForAge.ts',
    indicator: 'length/height-for-age',
    unit: 'cm',
  },
  {
    input: 'hcanthro.txt',
    output: 'headCircumferenceForAge.ts',
    indicator: 'head-circumference-for-age',
    unit: 'cm',
  },
];

/**
 * @param {string} text
 * @param {string} name
 */
function parseTable(text, name) {
  const lines = text.split(/\r?\n/).filter((line) => line.trim() !== '');
  const header = (lines.shift() ?? '').split('\t').map((h) => h.trim().toLowerCase());
  const col = (key) => {
    const idx = header.indexOf(key);
    if (idx < 0) throw new Error(`${name}: missing column "${key}"`);
    return idx;
  };
  const [iSex, iAge, iL, iM, iS] = ['sex', 'age', 'l', 'm', 's'].map(col);
  const iLoh = header.indexOf('loh');

  /** @type {{ 1: number[][]; 2: number[][] }} */
  const bySex = { 1: [], 2: [] };
  /** first age (days) flagged 'H' (standing height) per sex, if the table has an loh column */
  const heightFrom = { 1: null, 2: null };

  for (const [lineNo, line] of lines.entries()) {
    const cells = line.split('\t');
    const sex = Number(cells[iSex]);
    const age = Number(cells[iAge]);
    const lms = [cells[iL], cells[iM], cells[iS]].map(Number);
    if (sex !== 1 && sex !== 2) throw new Error(`${name}:${lineNo + 2}: bad sex "${cells[iSex]}"`);
    if (!Number.isInteger(age) || age < 0) throw new Error(`${name}:${lineNo + 2}: bad age`);
    if (lms.some((v) => !Number.isFinite(v)) || lms[1] <= 0 || lms[2] <= 0) {
      throw new Error(`${name}:${lineNo + 2}: bad LMS values`);
    }
    if (age > MAX_AGE_DAYS) continue;
    const rows = bySex[sex];
    if (age !== rows.length) {
      throw new Error(
        `${name}:${lineNo + 2}: expected age ${rows.length} for sex ${sex}, got ${age}`,
      );
    }
    rows.push(lms);
    if (iLoh >= 0 && heightFrom[sex] === null && cells[iLoh]?.trim() === 'H') heightFrom[sex] = age;
  }
  if (bySex[1].length === 0 || bySex[2].length === 0) throw new Error(`${name}: empty table`);
  return { bySex, heightFrom };
}

/** @param {number[][]} rows */
function formatRows(rows) {
  const out = [];
  for (let i = 0; i < rows.length; i += ROWS_PER_LINE) {
    const chunk = rows.slice(i, i + ROWS_PER_LINE).map((r) => `[${r.join(',')}]`);
    out.push(`    ${chunk.join(',')},`);
  }
  return out.join('\n');
}

mkdirSync(OUT_DIR, { recursive: true });

for (const table of TABLES) {
  const { bySex, heightFrom } = parseTable(
    readFileSync(join(SRC_DIR, table.input), 'utf8'),
    table.input,
  );
  const extra =
    heightFrom[1] !== null
      ? `\n * Ages >= ${heightFrom[1]} days (boys) / ${heightFrom[2]} days (girls) are standing height; younger are recumbent length.`
      : '';
  const source = `/* AUTO-GENERATED by scripts/build-who-data.mjs from data/who/${table.input} — DO NOT EDIT. */
/* eslint-disable */
/**
 * WHO Child Growth Standards (2006) — ${table.indicator} LMS parameters (M in ${table.unit}).
 * Index = age in completed days (0..${bySex[1].length - 1}). Row = [L, M, S].${extra}
 * Source: WHO anthro package, https://github.com/WorldHealthOrganization/anthro
 */
import type { LmsTable } from '../lms';

const table: LmsTable = {
  male: [
${formatRows(bySex[1])}
  ],
  female: [
${formatRows(bySex[2])}
  ],
};

export default table;
`;
  writeFileSync(join(OUT_DIR, table.output), source);
  console.log(
    `✓ ${table.output}: male ${bySex[1].length} rows, female ${bySex[2].length} rows (${(source.length / 1024).toFixed(1)} KiB)`,
  );
}
